contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address user,
        uint256 itemPrice,
        uint256 dailyAllowance,
        uint256 nrnLiquidity
    ) public payable {
        require(user != address(0));
        require(user != address(this));
        require(itemPrice > 0);
        require(dailyAllowance > 0);
        require(dailyAllowance <= type(uint16).max);
        require(nrnLiquidity >= itemPrice);

        address treasury = c.treasuryAddress(); if (__ESBMC_reverted()) return;

        c.createGameItem("item", "uri", false, true, 0, itemPrice, uint16(dailyAllowance)); if (__ESBMC_reverted()) return;
        uint256 tokenId = c.uniqueTokensOutstanding() - 1;

        uint256 userBalanceBefore = c.balanceOf(user, tokenId); if (__ESBMC_reverted()) return;
        uint256 allowanceBefore = c.getAllowanceRemaining(user, tokenId); if (__ESBMC_reverted()) return;

        c.mint(tokenId, 1); if (__ESBMC_reverted()) return;

        uint256 userBalanceAfter = c.balanceOf(user, tokenId); if (__ESBMC_reverted()) return;
        uint256 allowanceAfter = c.getAllowanceRemaining(user, tokenId); if (__ESBMC_reverted()) return;

        assert(
            userBalanceAfter == userBalanceBefore + 1 &&
            allowanceAfter == allowanceBefore - 1
        );
    }

    receive() external payable {}
}

